def collect(root,cache):
 papers=read(root/'docs/literature/omics-2023-2026/papers.json');verify_fixed_cohort(root,root/'docs/literature/omics-2023-2026',papers);definition=next(x for x in read(root/'docs/literature/omics-2023-2026/tool-inventory.json')if x['id']=='vep');pattern=re.compile(definition['pattern'],re.I);census=dict(schema_version=1,pattern=pattern.pattern,collector=pin(Path(collector.__file__)),sources={},contexts=[],other_structures=[]);selected={}
 for paper in papers:
  with gzip.open(cache/(paper['pmcid']+'.xml.gz'),'rb')as stream:raw=stream.read(16000001)
  require(len(raw)<=16000000 and hashlib.sha256(raw).hexdigest()==paper['xml_sha256'],'Primary XML differs');tree=ET.fromstring(raw);require(any((n.text or'').strip().lower()==paper['doi'].lower()for n in tree.findall('front/article-meta/article-id')),'Primary DOI differs');ps=list(collector.paragraphs(tree));census['sources'][paper['paper_id']]=dict(pmcid=paper['pmcid'],doi=paper['doi'],**identity(raw));anchors=[]
  for p in ps:
   if pattern.search(p['match_text']):
    entry=dict(paragraph_index=p['paragraph_index'],section=p['section'],paragraph_sha256=hashlib.sha256(p['text'].encode()).hexdigest(),matching_text_sha256=hashlib.sha256(p['match_text'].encode()).hexdigest());anchors.append(entry);census['contexts'].append(dict(paper_id=paper['paper_id'],**entry))
  for location in ['front/article-meta/abstract','back','floats-group','body//supplementary-material']:
   for node in tree.findall(location):
    if pattern.search(collector.matching_words(node)):census['other_structures'].append(dict(paper_id=paper['paper_id'],location=location,sha256=hashlib.sha256(ET.tostring(node)).hexdigest()))
  if any(t['tool_id']=='vep'for t in paper['tools']):require(paper['paper_id']in ROLES and anchors,'Unreviewed VEP member');selected[paper['paper_id']]=(paper,anchors)
 require(list(selected)==list(ROLES)and len(census['sources'])==250 and len(census['contexts'])==71,'Frozen VEP source population differs');roles=[];reviews=[]
 for pid,spec in ROLES.items():
  paper,anchors=selected[pid];use=next(t for t in paper['tools']if t['tool_id']=='vep');require(any(a['paragraph_index']==use['evidence_paragraph_index']and a['paragraph_sha256']==use['evidence_paragraph_sha256']for a in anchors),'Raw selected evidence differs');note=spec[2]+' Source review does not establish an executed author recipe or whole-paper reproduction.'
  role=dict(paper_id=pid,pmcid=paper['pmcid'],doi=paper['doi'],tool_id='vep',runtime=spec[0],primary_anchors=anchors,use_summary=spec[1],implementation_scope_note=note,reported_version_preserved=use['version_reported_near_name'],qualified_author_recipe=False,whole_paper_reproduced=False,source_review_already_counted=pid=='P192');roles.append(role)
  reviews.append(dict(pmcid=paper['pmcid'],doi=paper['doi'],tool_id='vep',evidence_paragraph_sha256=use['evidence_paragraph_sha256'],use_summary=role['use_summary'],implementation_scope_note=note,supporting_evidence=[a for a in anchors if a['paragraph_index']!=use['evidence_paragraph_index']]))
 return census,dict(schema_version=1,roles=roles,new_source_reviews=37,expanded_existing_reviews=1,source_audit_admits_runtime=False,whole_goal_complete=False),dict(schema_version=1,reviews=reviews)

def audit(root,cache):
 for name,value in zip(['CENSUS.json','ROLES.json','REVIEW-ENTRIES.json'],collect(root,cache)):require(read(root/FOLDER/name)==value,'Primary VEP source role differs: '+name)
 return dict(status='PASS250_VEP_PRIMARY_ROLES',sources=250,contexts=71,reviewed_roles=38,new_source_reviews=37,expanded_existing_reviews=1,source_audit_admits_runtime=False,whole_goal_complete=False)
if __name__=='__main__':
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--root',type=Path,default=ROOT);p.add_argument('--xml-cache',type=Path,required=True);p.add_argument('--write',action='store_true');a=p.parse_args();root=a.root.resolve()
 try:
  if a.write:
   folder=root/FOLDER;folder.mkdir()
   for name,value in zip(['CENSUS.json','ROLES.json','REVIEW-ENTRIES.json'],collect(root,a.xml_cache)):
    with(folder/name).open('xb')as out:out.write(encoded(value))
  print(json.dumps(audit(root,a.xml_cache),indent=2))
 except Exception as e:raise SystemExit('FAIL2: no complete VEP source-role audit; retain evidence and correct cause: '+str(e))
